def reopen_band(days):
    """Return the band for a ticket reopened days ago."""
    if days < 2:
        return "under 2"
    elif days < 7:
        return "2 to 7"
    else:
        return "over 7"

tasks.tests:
def _band_right(hours):
    if hours < 4:
        return "under 4"
    if hours <= 24:
        return "4 to 24"
    return "over 24"

def _band_round_1(hours):
    if hours < 4:
        return "under 4"
    elif hours < 24:
        return "4 to 24"
    else:
        return "over 24"

def _band_lower_edge(hours):
    if hours <= 4:
        return "under 4"
    if hours <= 24:
        return "4 to 24"
    return "over 24"

def _band_below_edge(hours):
    if hours < 3:
        return "under 4"
    if hours <= 24:
        return "4 to 24"
    return "over 24"

def _band_past_edge(hours):
    if hours < 4:
        return "under 4"
    if hours <= 25:
        return "4 to 24"
    return "over 24"

assert not raises(AssertionError, test_age_band_edges, _band_right), "called with a band function that meets the requirement, the test raises nothing"
assert raises(AssertionError, test_age_band_edges, _band_round_1), "called with the round-1 function, which gives \"over 24\" at 24, the test raises AssertionError"
assert (raises(AssertionError, test_age_band_edges, _band_lower_edge), raises(AssertionError, test_age_band_edges, _band_below_edge)) == (True, True), "called with a function wrong at 3 or at 4, the test raises AssertionError"
assert raises(AssertionError, test_age_band_edges, _band_past_edge), "called with a function that gives \"4 to 24\" at 25, the test raises AssertionError"
